    expect(await res.json()).toMatchObject({ title: "Plan the week", done: false });
  });

  it("rejects a to-do without a title", async () => {
    expect((await post({ title: "  " })).status).toBe(400);
  });

  it("returns 404 for a to-do that doesn't exist", async () => {
